    static final Pattern URL_PARTS = Pattern.compile("^([A-Za-z][A-Za-z0-9+.-]*):(//[^/?#]*)?(.*)$", Pattern.DOTALL);

    /** The URL — or, with PQA_BASE_URL set and the URL on the site of the first page opened, the same page there. */
