/** Every action type — a Pocket QA scenario. */
public class EveryActionTypeTest {
    static final Duration TIMEOUT = Duration.ofMillis(10000);
    static final String BROWSER = "Chrome";
    static final String HEADLESS = "0";

    WebDriver driver;
    String firstOrigin;
    // The step running now, which a failure names.
    String at = "";

    // The extension's own in-page code (popup/export/page-js.js), run through executeScript.
    static final String FIND_TEXT_JS = String.join("\n",
        "return ((text, tag) => {",
        "  if (tag) return Array.from(document.querySelectorAll(tag)).find(el => el.textContent.trim() === text) || null;",
        "  const want = String(text).trim();",
        "  const holds = (el) => el.tagName !== 'SCRIPT' && el.tagName !== 'STYLE' && el.textContent.trim() === want;",
        "  const walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_ELEMENT, {",
        "    acceptNode: (el) => (el.textContent.includes(want) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT),",
        "  });",
        "  let hit = null;",
        "  for (let el = walker.nextNode(); el; el = walker.nextNode()) {",
        "    if (hit && !hit.contains(el)) break;",
        "    if (holds(el)) hit = el;",
        "  }",
        "  return hit;",
        "}).apply(null, arguments)");

    static final String QUERY_DEEP_JS = String.join("\n",
        "return ((selector) => {",
        "  const deep = (root) => {",
        "    const el = root.querySelector(selector);",
        "    if (el) return el;",
        "    for (const host of root.querySelectorAll('*')) {",
        "      if (host.shadowRoot) {",
        "        const found = deep(host.shadowRoot);",
        "        if (found) return found;",
        "      }",
        "    }",
        "    return null;",
        "  };",
        "  try { return deep(document); } catch (e) { return null; }",
        "}).apply(null, arguments)");

    static final String SET_INPUT_JS = String.join("\n",
        "return ((el, value) => {",
        "  el.scrollIntoView({ behavior: 'auto', block: 'center' });",
        "  el.focus();",
        "  const v = value ?? '';",
        "  if (el.isContentEditable) {",
        "    document.execCommand('selectAll', false, null);",
        "    document.execCommand('insertText', false, v);",
        "    el.dispatchEvent(new Event('input', { bubbles: true }));",
        "    el.dispatchEvent(new Event('change', { bubbles: true }));",
        "    return;",
        "  }",
        "  if (el.tagName === 'SELECT') {",
        "    const want = String(v);",
        "    const options = Array.from(el.options);",
        "    const option = options.find(o => o.value === want) || options.find(o => o.text === want);",
        "    if (!option) throw new Error('The dropdown has no option \"' + want + '\"');",
        "    el.value = option.value;",
        "    el.dispatchEvent(new Event('input', { bubbles: true, cancelable: true }));",
        "    el.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));",
        "    el.dispatchEvent(new Event('blur', { bubbles: true }));",
        "    el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));",
        "    return;",
        "  }",
        "  let setter = null;",
        "  for (let p = Object.getPrototypeOf(el); p && p !== Object.prototype; p = Object.getPrototypeOf(p)) {",
        "    const d = Object.getOwnPropertyDescriptor(p, 'value');",
        "    if (d?.set) { setter = d.set; break; }",
        "  }",
        "  if (setter) setter.call(el, v); else el.value = v;",
        "  el.dispatchEvent(new Event('input', { bubbles: true }));",
        "  el.dispatchEvent(new Event('change', { bubbles: true }));",
        "  el.dispatchEvent(new Event('blur', { bubbles: true }));",
        "}).apply(null, arguments)");

    static final String FIND_CHILD_JS = String.join("\n",
        "return ((parent, cond) => {",
        "  const _fbRe = /^\\{fallback:(.+)\\}$/;",
        "  const _fbField = ['valueEquals','textContains','idContains','classContains','typeEquals'].find(f => cond[f] != null && _fbRe.test(String(cond[f])));",
        "  const _fbVals  = _fbField ? String(cond[_fbField]).match(_fbRe)[1].split('|').map(s=>s.trim()) : null;",
        "  const _tryFind = (c, blankField) => {",
        "    const mode = c.matchMode || 'any';",
        "    const norm = s => (s == null ? '' : String(s).trim().toLowerCase());",
        "    const checks = [];",
        "    if (c.valueEquals   != null && c.valueEquals   !== '') checks.push(el => el.value !== undefined && String(el.value) === String(c.valueEquals));",
        "    if (c.textContains  != null && c.textContains  !== '') {",
        "      // The element's own text (its text nodes, not its children's) or all of it, as playback matches.",
        "      const n = norm(c.textContains);",
        "      const own = el => [...el.childNodes].filter(x => x.nodeType === 3).map(x => x.textContent).join('');",
        "      checks.push(el => norm(own(el)).includes(n) || norm(el.textContent).includes(n));",
        "    }",
        "    if (c.idContains    != null && c.idContains    !== '') { const n = norm(c.idContains);    checks.push(el => norm(el.id).includes(n)); }",
        "    if (c.classContains != null && c.classContains !== '') { const n = norm(c.classContains); checks.push(el => norm(el.className).includes(n)); }",
        "    if (c.typeEquals    != null && c.typeEquals    !== '') checks.push(el => (c.typeEquals === 'select' ? el.tagName === 'SELECT' : el.type === c.typeEquals));",
        "    if (blankField) checks.push(el => {",
        "      if (blankField === 'valueEquals')   return el.value !== undefined && String(el.value) === '';",
        "      if (blankField === 'textContains')  return norm(el.textContent) === '';",
        "      if (blankField === 'idContains')    return !el.id;",
        "      if (blankField === 'classContains') return norm(el.getAttribute('class')) === '';",
        "      return !el.getAttribute('type');",
        "    });",
        "    if (!checks.length) return null;",
        "    const test = mode === 'all' ? el => checks.every(fn => fn(el)) : el => checks.some(fn => fn(el));",
        "    const first = (root) => {",
        "      const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);",
        "      for (let node = walker.nextNode(); node; node = walker.nextNode()) { if (test(node)) return node; }",
        "      return null;",
        "    };",
        "    let hit = first(parent);",
        "    if (hit && c.textContains != null && c.textContains !== '') { for (let inner = first(hit); inner; inner = first(hit)) hit = inner; }",
        "    return hit;",
        "  };",
        "  if (_fbField && _fbVals) {",
        "    for (const _fv of _fbVals) { const el = _tryFind({...cond, [_fbField]: _fv}, _fv === '' ? _fbField : null); if (el) return el; }",
        "    return null;",
        "  }",
        "  return _tryFind(cond);",
        "}).apply(null, arguments)");

    static final String READ_VAL_JS = String.join("\n",
        "return ((el, from, attr) => {",
        "  const tag = String(el.tagName || '').toUpperCase(), fld = tag === 'INPUT' || tag === 'TEXTAREA';",
        "  const txt = () => (typeof el.innerText === 'string' ? el.innerText : (el.textContent || ''));",
        "  const ws = (s) => String(s == null ? '' : s).replace(/\\s+/g, ' ').trim();",
        "  if (from === 'attr') return el.getAttribute(attr) ?? '';",
        "  if (from === 'value') {",
        "    if (tag === 'SELECT' && el.multiple) return Array.from(el.selectedOptions).map(o => o.value).join(', ');",
        "    if (fld || tag === 'SELECT') return el.value ?? '';",
        "    if (el.isContentEditable) return txt().trim();",
        "    if (typeof el.value === 'string' && el.value !== '') return el.value;",
        "    if (typeof el.value === 'number' && tag !== 'LI') return String(el.value);",
        "    return txt().trim();",
        "  }",
        "  if (from === 'visible') {",
        "    if (tag === 'SELECT') return Array.from(el.selectedOptions).map(o => ws(o.text)).join(', ');",
        "    if (fld) return el.value ?? '';",
        "    return ws(txt());",
        "  }",
        "  return (el.textContent || '').trim();",
        "}).apply(null, arguments)");

    /** PQA_BROWSER (Chrome, Edge, Firefox or Safari), else the exported one; PQA_HEADLESS=1: no window, at a desktop size. */
    static WebDriver startBrowser() {
        String name = System.getenv().getOrDefault("PQA_BROWSER", BROWSER);
        boolean headless = "1".equals(System.getenv().getOrDefault("PQA_HEADLESS", HEADLESS));
        switch (name) {
            case "Safari":
                return new SafariDriver();
            case "Firefox": {
                FirefoxOptions options = new FirefoxOptions();
                if (headless) options.addArguments("-headless", "--width=1920", "--height=1080");
                return new FirefoxDriver(options);
            }
            case "Edge": {
                EdgeOptions options = new EdgeOptions();
                if (headless) options.addArguments("--headless=new", "--window-size=1920,1080");
                return new EdgeDriver(options);
            }
            case "Chrome": {
                ChromeOptions options = new ChromeOptions();
                if (headless) options.addArguments("--headless=new", "--window-size=1920,1080");
                return new ChromeDriver(options);
            }
            default:
                throw new IllegalArgumentException("PQA_BROWSER=" + name + ": not Chrome, Edge, Firefox or Safari");
        }
    }

    /** A variable's value: PQA_<name> from the environment when it is set, else the exported one. */
    static String var(String name, String value) {
        String set = System.getenv("PQA_" + name);
        return set != null ? set : value;
    }

    static final Pattern URL_PARTS = Pattern.compile("^([A-Za-z][A-Za-z0-9+.-]*):(//[^/?#]*)?(.*)$", Pattern.DOTALL);

    /** The URL — or, with PQA_BASE_URL set and the URL on the site of the first page opened, the same page there. */
    String url(String u) {
        Matcher m = URL_PARTS.matcher(u);
        if (!m.matches()) return u;
        String origin = m.group(1).toLowerCase() + ":" + (m.group(2) == null ? "" : m.group(2));
        if (firstOrigin == null) firstOrigin = origin;
        String base = System.getenv("PQA_BASE_URL");
        if (base == null || base.isEmpty() || !origin.equals(firstOrigin)) return u;
        return base.replaceAll("/+$", "") + m.group(3);
    }

    Object exec(String script, Object... args) {
        return ((JavascriptExecutor) driver).executeScript(script, args);
    }

    /** A CSS selector, looked for inside open shadow roots too when the page has no match. */
    static By css(String selector) {
        return new By() {
            @Override
            public List<WebElement> findElements(SearchContext context) {
                List<WebElement> found = context.findElements(By.cssSelector(selector));
                if (!found.isEmpty()) return found;
                Object el = ((JavascriptExecutor) context).executeScript(QUERY_DEEP_JS, selector);
                return el instanceof WebElement ? List.of((WebElement) el) : List.of();
            }

            @Override
            public String toString() {
                return "css: " + selector;
            }
        };
    }

    /** The extension's Text search: the innermost element whose trimmed text is the text, of the tag when given. */
    static By text(String text, String tag) {
        return new By() {
            @Override
            public List<WebElement> findElements(SearchContext context) {
                Object el = ((JavascriptExecutor) context).executeScript(FIND_TEXT_JS, text, tag);
                return el instanceof WebElement ? List.of((WebElement) el) : List.of();
            }

            @Override
            public String toString() {
                return "text: " + text;
            }
        };
    }

    /** The first element the locators find now, in their order, or null; a selector the browser cannot parse is passed over. */
    WebElement locate(By... locators) {
        for (By by : locators) {
            try {
                List<WebElement> found = driver.findElements(by);
                if (!found.isEmpty()) return found.get(0);
            } catch (InvalidSelectorException e) {
                // as playback passes it over
            }
        }
        return null;
    }

    /** A step's element, waited for up to TIMEOUT. */
    WebElement find(By... locators) {
        return waitFor(false, locators);
    }

    /** A step's element to click: displayed and enabled too. */
    WebElement findClickable(By... locators) {
        return waitFor(true, locators);
    }

    WebElement waitFor(boolean clickable, By... locators) {
        return new WebDriverWait(driver, TIMEOUT)
            .ignoring(StaleElementReferenceException.class)
            .withMessage("no element found by " + Arrays.toString(locators))
            .until(d -> {
                WebElement el = locate(locators);
                return el != null && (!clickable || (el.isDisplayed() && el.isEnabled())) ? el : null;
            });
    }

    byte[] pageShot() {
        return ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);
    }

    static void save(String file, byte[] png) throws IOException {
        Files.write(Paths.get(file), png);
    }

    static final Set<String> SCRIPT_INPUT_TYPES = Set.of("date", "time", "datetime-local", "month", "week", "color", "range");

    /**
     * An Input as the extension makes it: a <select> chooses the option of that value, else of that text; a date, time,
     * color or range field gets the value as the extension sets it; any other field is typed into.
     */
    void input(WebElement el, String value) {
        if (el.getTagName().equalsIgnoreCase("select")) {
            Select select = new Select(el);
            try {
                select.selectByValue(value);
            } catch (RuntimeException e) {
                select.selectByVisibleText(value);
            }
        } else if (SCRIPT_INPUT_TYPES.contains(String.valueOf(el.getDomProperty("type")))) {
            exec(SET_INPUT_JS, el, value);
        } else {
            el.clear();
            el.sendKeys(value);
        }
    }

    /** The child a Child Condition picks in its parent (content.js findElementByCondition): criteria as name, value pairs. */
    WebElement findChild(WebElement parent, int step, String... criteria) {
        Map<String, String> cond = new LinkedHashMap<>();
        for (int k = 0; k + 1 < criteria.length; k += 2) cond.put(criteria[k], criteria[k + 1]);
        Object el = exec(FIND_CHILD_JS, parent, cond);
        if (!(el instanceof WebElement)) throw new IllegalStateException("Child condition not matched (step " + step + ")");
        return (WebElement) el;
    }

    /** What Read DOM reads (content.js readElementValue). */
    String readVal(WebElement el, String from, String attr) {
        Object value = exec(READ_VAL_JS, el, from, attr);
        return value == null ? "" : value.toString();
    }

    /** The whole page, not just the window, as the browser can: Firefox its own way, Chrome and Edge through CDP, Safari only the window. */
    @SuppressWarnings("unchecked")
    byte[] fullPageShot() {
        if (driver instanceof HasFullPageScreenshot) return ((HasFullPageScreenshot) driver).getFullPageScreenshotAs(OutputType.BYTES);
        if (!(driver instanceof HasCdp)) return pageShot();
        HasCdp cdp = (HasCdp) driver;
        Map<String, Object> size = (Map<String, Object>) cdp.executeCdpCommand("Page.getLayoutMetrics", Map.of()).get("cssContentSize");
        Map<String, Object> clip = Map.of("x", 0, "y", 0, "width", size.get("width"), "height", size.get("height"), "scale", 1);
        Map<String, Object> shot = cdp.executeCdpCommand("Page.captureScreenshot", Map.of("format", "png", "captureBeyondViewport", true, "clip", clip));
        return Base64.getDecoder().decode((String) shot.get("data"));
    }

    /** A value put into a Script step's code, escaped as the extension escapes it. */
    static String js(String v) {
        return v.replace("\\", "\\\\").replace("\"", "\\\"").replace("'", "\\'").replace("`", "\\`")
            .replace("$" + "{", "\\$" + "{").replace("\n", "\\n").replace("\r", "\\r");
    }

    static final String LETTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    static final String DIGITS = "0123456789";

    /** A Random variable's value: length characters of chars. */
    static String random(String chars, int length) {
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < length; k++) out.append(chars.charAt(ThreadLocalRandom.current().nextInt(chars.length())));
        return out.toString();
    }

    /** A Pick variable's value: one of them, at random. */
    static String pick(String... values) {
        return values[ThreadLocalRandom.current().nextInt(values.length)];
    }

    /** Stops the test where a run stops, with its message; as a boolean, it can open a block a step would. */
    static boolean stop(String message) {
        throw new IllegalStateException(message);
    }

    @BeforeMethod
    public void setUp() {
        driver = startBrowser();
        driver.manage().timeouts().scriptTimeout(TIMEOUT.plusSeconds(5));
    }

    /** A failed test leaves the page as its step left it: <class>_failure.png. */
    @AfterMethod(alwaysRun = true)
    public void tearDown(ITestResult result) {
        if (driver == null) return;
        try {
            if (result.getStatus() == ITestResult.FAILURE) save(getClass().getSimpleName() + "_failure.png", pageShot());
        } catch (Exception e) {
            // no picture: the step's own error is what is reported
        } finally {
            driver.quit();
        }
    }

