/** Conditions — a Pocket QA scenario. */
public class ConditionsTest {
    static final Duration TIMEOUT = Duration.ofMillis(10000);
    static final String BROWSER = "Chrome";
    static final String HEADLESS = "0";

    WebDriver driver;
    String firstOrigin;
    // The step running now, which a failure names.
    String at = "";

    // The extension's own in-page code (popup/export/page-js.js), run through executeScript.
    static final String FIND_TEXT_JS = String.join("\n",
        "return ((text, tag) => {",
        "  if (tag) return Array.from(document.querySelectorAll(tag)).find(el => el.textContent.trim() === text) || null;",
        "  const want = String(text).trim();",
        "  const holds = (el) => el.tagName !== 'SCRIPT' && el.tagName !== 'STYLE' && el.textContent.trim() === want;",
        "  const walker = document.createTreeWalker(document.body || document.documentElement, NodeFilter.SHOW_ELEMENT, {",
        "    acceptNode: (el) => (el.textContent.includes(want) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT),",
        "  });",
        "  let hit = null;",
        "  for (let el = walker.nextNode(); el; el = walker.nextNode()) {",
        "    if (hit && !hit.contains(el)) break;",
        "    if (holds(el)) hit = el;",
        "  }",
        "  return hit;",
        "}).apply(null, arguments)");

    static final String QUERY_DEEP_JS = String.join("\n",
        "return ((selector) => {",
        "  const deep = (root) => {",
        "    const el = root.querySelector(selector);",
        "    if (el) return el;",
        "    for (const host of root.querySelectorAll('*')) {",
        "      if (host.shadowRoot) {",
        "        const found = deep(host.shadowRoot);",
        "        if (found) return found;",
        "      }",
        "    }",
        "    return null;",
        "  };",
        "  try { return deep(document); } catch (e) { return null; }",
        "}).apply(null, arguments)");

    static final String SET_INPUT_JS = String.join("\n",
        "return ((el, value) => {",
        "  el.scrollIntoView({ behavior: 'auto', block: 'center' });",
        "  el.focus();",
        "  const v = value ?? '';",
        "  if (el.isContentEditable) {",
        "    document.execCommand('selectAll', false, null);",
        "    document.execCommand('insertText', false, v);",
        "    el.dispatchEvent(new Event('input', { bubbles: true }));",
        "    el.dispatchEvent(new Event('change', { bubbles: true }));",
        "    return;",
        "  }",
        "  if (el.tagName === 'SELECT') {",
        "    const want = String(v);",
        "    const options = Array.from(el.options);",
        "    const option = options.find(o => o.value === want) || options.find(o => o.text === want);",
        "    if (!option) throw new Error('The dropdown has no option \"' + want + '\"');",
        "    el.value = option.value;",
        "    el.dispatchEvent(new Event('input', { bubbles: true, cancelable: true }));",
        "    el.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));",
        "    el.dispatchEvent(new Event('blur', { bubbles: true }));",
        "    el.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));",
        "    return;",
        "  }",
        "  let setter = null;",
        "  for (let p = Object.getPrototypeOf(el); p && p !== Object.prototype; p = Object.getPrototypeOf(p)) {",
        "    const d = Object.getOwnPropertyDescriptor(p, 'value');",
        "    if (d?.set) { setter = d.set; break; }",
        "  }",
        "  if (setter) setter.call(el, v); else el.value = v;",
        "  el.dispatchEvent(new Event('input', { bubbles: true }));",
        "  el.dispatchEvent(new Event('change', { bubbles: true }));",
        "  el.dispatchEvent(new Event('blur', { bubbles: true }));",
        "}).apply(null, arguments)");

    static final String CHECK_COND_JS = String.join("\n",
        "return ((type, el, expected) => {",
        "  const shown = (e) => {",
        "    const style = getComputedStyle(e), rect = e.getBoundingClientRect();",
        "    return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0' && rect.width > 0 && rect.height > 0;",
        "  };",
        "  switch (type) {",
        "    case 'elementExists':    return !!el;",
        "    case 'elementNotExists': return !el;",
        "    case 'elementVisible':   return !!el && shown(el);",
        "    case 'elementHidden':    return !el || !shown(el);",
        "    case 'textContains':     return !!el && el.textContent.includes(expected);",
        "    case 'textEquals':       return !!el && el.textContent.trim() === (expected || '').trim();",
        "    case 'valueEquals':      return !!el && 'value' in el && el.value === expected;",
        "    case 'valueContains':    return !!el && 'value' in el && el.value.includes(expected);",
        "    case 'urlContains':      return window.location.href.includes(expected);",
        "    case 'urlEquals':        return window.location.href === expected;",
        "    case 'hasClass':         return !!el && el.classList.contains(expected);",
        "    case 'hasAttribute': {",
        "      if (!el) return false;",
        "      const eq = (expected || '').indexOf('=');",
        "      if (eq < 0) return el.hasAttribute(expected);",
        "      const name = expected.slice(0, eq);",
        "      return el.hasAttribute(name) && el.getAttribute(name) === expected.slice(eq + 1);",
        "    }",
        "    default: throw new Error('Unknown condition type \"' + type + '\"');",
        "  }",
        "}).apply(null, arguments)");

    /** PQA_BROWSER (Chrome, Edge, Firefox or Safari), else the exported one; PQA_HEADLESS=1: no window, at a desktop size. */
    static WebDriver startBrowser() {
        String name = System.getenv().getOrDefault("PQA_BROWSER", BROWSER);
        boolean headless = "1".equals(System.getenv().getOrDefault("PQA_HEADLESS", HEADLESS));
        switch (name) {
            case "Safari":
                return new SafariDriver();
            case "Firefox": {
                FirefoxOptions options = new FirefoxOptions();
                if (headless) options.addArguments("-headless", "--width=1920", "--height=1080");
                return new FirefoxDriver(options);
            }
            case "Edge": {
                EdgeOptions options = new EdgeOptions();
                if (headless) options.addArguments("--headless=new", "--window-size=1920,1080");
                return new EdgeDriver(options);
            }
            case "Chrome": {
                ChromeOptions options = new ChromeOptions();
                if (headless) options.addArguments("--headless=new", "--window-size=1920,1080");
                return new ChromeDriver(options);
            }
            default:
                throw new IllegalArgumentException("PQA_BROWSER=" + name + ": not Chrome, Edge, Firefox or Safari");
        }
    }

    /** A variable's value: PQA_<name> from the environment when it is set, else the exported one. */
    static String var(String name, String value) {
        String set = System.getenv("PQA_" + name);
        return set != null ? set : value;
    }

    static final Pattern URL_PARTS = Pattern.compile("^([A-Za-z][A-Za-z0-9+.-]*):(//[^/?#]*)?(.*)$", Pattern.DOTALL);

    /** The URL — or, with PQA_BASE_URL set and the URL on the site of the first page opened, the same page there. */
    String url(String u) {
        Matcher m = URL_PARTS.matcher(u);
        if (!m.matches()) return u;
        String origin = m.group(1).toLowerCase() + ":" + (m.group(2) == null ? "" : m.group(2));
        if (firstOrigin == null) firstOrigin = origin;
        String base = System.getenv("PQA_BASE_URL");
        if (base == null || base.isEmpty() || !origin.equals(firstOrigin)) return u;
        return base.replaceAll("/+$", "") + m.group(3);
    }

    Object exec(String script, Object... args) {
        return ((JavascriptExecutor) driver).executeScript(script, args);
    }

    /** A CSS selector, looked for inside open shadow roots too when the page has no match. */
    static By css(String selector) {
        return new By() {
            @Override
            public List<WebElement> findElements(SearchContext context) {
                List<WebElement> found = context.findElements(By.cssSelector(selector));
                if (!found.isEmpty()) return found;
                Object el = ((JavascriptExecutor) context).executeScript(QUERY_DEEP_JS, selector);
                return el instanceof WebElement ? List.of((WebElement) el) : List.of();
            }

            @Override
            public String toString() {
                return "css: " + selector;
            }
        };
    }

